/*
 * A137374  Triangular array of the coefficients of the Jacobsthal-Lucas
 *          polynomials ordered by descending powers, read by rows.
 * https://oeis.org/A137374
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(0)=2, a(1)=1; coefficients of Jacobsthal–Lucas polynomials
 *            generated by p(n)=2*x*p(n-2)+p(n-1); result is the flattened
 *            triangle of these coefficients
 * Range:     u8 n <= 30, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* external linkage as required */
seq_t a(idx_t n)
{
    /* static cache of already computed terms */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;

    /* static rolling arrays for the last two rows */
    static seq_t *prev2 = NULL;
    static size_t len2 = 0;
    static seq_t *prev1 = NULL;
    static size_t len1 = 0;
    static size_t next_row = 0;

    /* initialise cache on first call */
    if (cache == NULL) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }

    /* build rows until we have at least n+1 terms */
    while (cache_len <= (size_t)n) {
        /* --- compute next row ---------------------------------------- */
        if (next_row == 0) {                /* row 0: p(0) = 2   */
            seq_t *row = (seq_t *)malloc(sizeof(seq_t));
            row[0] = (seq_t)2;

            /* append term to cache */
            if (cache_len + 1 > cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 128;
                while (new_cap < cache_len + 1) new_cap *= 2;
                cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                cache_cap = new_cap;
            }
            cache[cache_len++] = row[0];

            prev2 = row;  len2 = 1;
            next_row++;
            continue;
        }

        if (next_row == 1) {                /* row 1: p(1) = 1   */
            seq_t *row = (seq_t *)malloc(sizeof(seq_t));
            row[0] = (seq_t)1;

            if (cache_len + 1 > cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 128;
                while (new_cap < cache_len + 1) new_cap *= 2;
                cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                cache_cap = new_cap;
            }
            cache[cache_len++] = row[0];

            prev1 = row;  len1 = 1;
            next_row++;
            continue;
        }

        /* rows n >= 2 */
        size_t len = (next_row / 2) + 1;          /* floor(n/2)+1   */
        seq_t *row = (seq_t *)malloc(len * sizeof(seq_t));

        for (size_t k = 0; k < len; ++k) {
            seq_t val = 0;
            if (k < len1)            val += prev1[k];
            if (k > 0 && k - 1 < len2) val += (seq_t)2 * prev2[k - 1];
            row[k] = val;
        }

        /* ensure cache capacity */
        if (cache_len + len > cache_cap) {
            size_t new_cap = cache_cap ? cache_cap * 2 : 128;
            while (new_cap < cache_len + len) new_cap *= 2;
            cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            cache_cap = new_cap;
        }

        /* append row in reverse order (descending powers) */
        for (size_t j = len; j > 0; --j) {
            cache[cache_len++] = row[j - 1];
        }

        /* shift rows for next iteration */
        free(prev2);
        prev2 = prev1;  len2 = len1;
        prev1 = row;    len1 = len;

        next_row++;
    }

    return cache[(size_t)n];
}
